package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Usage.VectorStores.List(
		context.TODO(),
		openai.AdminOrganizationUsageVectorStoreListParams{
			StartTime: 1,
			EndTime: param.NewOpt[int64](1),
			BucketWidth: param.NewOpt[openai.AdminOrganizationUsageVectorStoresListBucketWidth](openai.AdminOrganizationUsageVectorStoresListBucketWidth1m),
			ProjectIds: []string{"string"},
			GroupBy: []string{"project_id"},
			Limit: param.NewOpt[int64](1),
			Page: param.NewOpt[string]("page"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
